//! Video probe with a simulated decoder: one consumer thread takes each unit
//! from the session's `VideoSink`, spends a fixed decode delay on it, then
//! presents it. It prints the receive and present intervals and the fps cap
//! the viewer derived. It never requests input control and is not a UI
//! presentation or latency measurement.
//! Read only a dedicated expiring controller.json generated by `deployed`.
//! Run: viewer_probe CONTROLLER_JSON SECONDS DECODE_MS auto|relay [DUMP_PATH]
//! [--codec h264|h265]. `h265` offers H.265 beside H.264, as the app does
//! when it can decode it; the host picks, and the report says which.
use pb_mapper_client::sdk::{Client, ClientConfig, ConnectOptions, PathPolicy, RelayTransport};
use pb_mapper_desktop::{
    Invitation, Pull, QualityPreset, VideoCodec, VideoLimits, Viewer, ViewerConfig, ViewerState,
};
use serde::Deserialize;
use std::{
    io::Write,
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    time::{Duration, Instant},
};

#[derive(Deserialize)]
struct Setup {
    server: String,
    credential: String,
    transport: RelayTransport,
    invitation: String,
    /// The host's LAN-first, which the viewer follows; one from an older
    /// `deployed` says nothing, which reads as on.
    #[serde(default = "lan_first_by_default")]
    lan_first: bool,
}

fn lan_first_by_default() -> bool {
    true
}

/// What the simulated decoder saw.
#[derive(Default)]
struct Decoded {
    units: u64,
    unique: u64,
    keyframes: u64,
    discontinuities: u64,
    bytes: u64,
    /// Network receipt intervals of non-duplicate units after warm-up, in ms.
    receive_gaps: Vec<f64>,
}

/// p50, p95 and max of `samples`, in ms.
fn spread(samples: &mut [f64]) -> Option<(f64, f64, f64)> {
    samples.sort_by(f64::total_cmp);
    let last = samples.len().checked_sub(1)?;
    Some((samples[last / 2], samples[last * 95 / 100], samples[last]))
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    let setup: Setup = serde_json::from_slice(&std::fs::read(
        args.get(1).ok_or("controller.json required")?,
    )?)?;
    let seconds: u64 = args.get(2).ok_or("seconds required")?.parse()?;
    let decode_ms: u64 = args
        .get(3)
        .ok_or("simulated decode delay ms required")?
        .parse()?;
    if !(5..=120).contains(&seconds) || decode_ms > 1000 {
        return Err("probe bounds: seconds 5..120, decode delay 0..1000".into());
    }
    let path = match args.get(4).map(String::as_str) {
        Some("auto") => PathPolicy::Auto,
        Some("relay") => PathPolicy::RelayOnly,
        _ => return Err("path must be auto or relay".into()),
    };
    let codecs = match args
        .windows(2)
        .find(|pair| pair[0] == "--codec")
        .map(|pair| pair[1].as_str())
    {
        None | Some("h264") => vec![VideoCodec::H264],
        Some("h265") => vec![VideoCodec::H265, VideoCodec::H264],
        Some(_) => return Err("--codec must be h264 or h265".into()),
    };
    let mut dump = args
        .get(5)
        .filter(|arg| !arg.starts_with("--"))
        .map(std::fs::File::create)
        .transpose()?
        .map(std::io::BufWriter::new);
    let client = Client::new(ClientConfig {
        server: setup.server,
        credential: setup.credential,
        keep_alive: true,
        namespace: None,
    })?
    .with_relay_transport(setup.transport)?;
    let viewer = Viewer::connect(
        &client,
        &Invitation::decode(&setup.invitation)?,
        ConnectOptions {
            path,
            lan_first: setup.lan_first,
            ..Default::default()
        },
        ViewerConfig {
            codecs,
            limits: VideoLimits {
                max_width: 1920,
                max_height: 1080,
                max_fps: 60,
            },
            fps_override: false,
            quality: QualityPreset::Balanced,
            progress: None,
        },
    )
    .await?;
    let consumer = viewer.video_sink().attach()?;
    let stop = Arc::new(AtomicBool::new(false));
    let done = stop.clone();
    let start = Instant::now();
    let warmup = Duration::from_secs(5);
    let decoder = std::thread::spawn(move || -> std::io::Result<Decoded> {
        let mut decoded = Decoded::default();
        let mut previous = None;
        while !done.load(Ordering::Acquire) {
            let unit = match consumer.next(Duration::from_millis(100), 4 << 20) {
                Pull::Unit(unit) => unit,
                Pull::Closed => break,
                _ => continue,
            };
            decoded.units += 1;
            decoded.keyframes += u64::from(unit.keyframe);
            decoded.discontinuities += u64::from(unit.discontinuity);
            decoded.bytes += unit.bytes.len() as u64;
            if !unit.duplicate {
                decoded.unique += 1;
                if unit.received_at.saturating_duration_since(start) >= warmup
                    && let Some(previous) = previous
                {
                    decoded
                        .receive_gaps
                        .push(unit.received_at.duration_since(previous).as_secs_f64() * 1000.0);
                }
                previous = Some(unit.received_at);
            }
            if let Some(dump) = &mut dump {
                dump.write_all(&unit.bytes)?;
            }
            std::thread::sleep(Duration::from_millis(decode_ms));
            consumer.presented(unit.generation, unit.frame_id);
        }
        if let Some(dump) = &mut dump {
            dump.flush()?;
        }
        Ok(decoded)
    });
    let watched = async {
        while start.elapsed() < Duration::from_secs(seconds) {
            tokio::time::sleep(Duration::from_millis(250)).await;
            let status = viewer.status();
            if matches!(
                status.state,
                ViewerState::Stopped | ViewerState::CaptureUnavailable
            ) {
                return Err(format!("{:?}: {}", status.reason, status.message));
            }
        }
        Ok(viewer.status())
    }
    .await;
    stop.store(true, Ordering::Release);
    let decoded = decoder.join().map_err(|_| "the decoder thread panicked")?;
    viewer.stop().await?;
    let status = watched?;
    let mut decoded = decoded?;
    let elapsed = start.elapsed().as_secs_f64();
    let stats = &status.stats;
    println!(
        "simulated_decoder=true seconds={elapsed:.3} decode_ms={decode_ms} path={} codec={:?} units={} unique_fps={:.2} keyframes={} discontinuities={} mbps={:.3} speed_rx_bps={} source_fps={:.2} presented_fps={:.2} fps_cap={} video={}x{} bitrate={} dropped={} backlog_drops={} keyframes_requested={} picture_latency_ms={:?}",
        stats.path,
        stats.codec,
        decoded.units,
        decoded.unique as f64 / elapsed,
        decoded.keyframes,
        decoded.discontinuities,
        decoded.bytes as f64 * 8.0 / elapsed / 1e6,
        stats.speed_rx_bps,
        stats.capture_fps,
        stats.presented_fps,
        stats.fps_cap,
        stats.width,
        stats.height,
        stats.bitrate,
        stats.dropped_frames,
        stats.backlog_drops,
        stats.keyframes_requested,
        stats.picture_latency_ms,
    );
    let present = stats.present_interval;
    println!(
        "present_interval_p50_ms={} present_interval_p95_ms={} present_interval_max_ms={} gaps_100={} gaps_250={}",
        present.p50_ms, present.p95_ms, present.max_ms, present.gaps_100, present.gaps_250
    );
    if let Some((p50, p95, max)) = spread(&mut decoded.receive_gaps) {
        println!(
            "warmup_seconds={} receive_gap_p50_ms={p50:.2} receive_gap_p95_ms={p95:.2} receive_gap_max_ms={max:.2}",
            warmup.as_secs()
        );
    }
    Ok(())
}
